package main

import "testing"

func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestIntegerOperation(t *testing.T) {
	var op integerOperation = addition{}
	if got := op.Apply(2, 3); got != 5 {
		t.Fatalf("addition.Apply(2, 3) = %d, want 5", got)
	}
	if got := add(4, 5); got != op.Apply(4, 5) {
		t.Fatalf("add(4, 5) = %d, want %d", got, op.Apply(4, 5))
	}
}

